window.NEON_UPLOADED_ALMONSEF_SECTIONS_6_9_20260829 = [{"id":"qdq-almonsef-s6-9-001","q":"أوجد قيمة: (٥⁸ + ٥⁷) ÷ ٥⁷.","options":["٦","٧","٨","٩"],"answer":0,"explain":"٥⁸ = ٥×٥⁷، لذا (٥×٥⁷ + ٥⁷) ÷ ٥⁷ = ٦.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"exponents","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-002","q":"دائرة قطرها ٤ سم، والجزء المظلل يمثل نصف مساحة الدائرة. قارن بين القيمة الأولى: مساحة الجزء المظلل، والقيمة الثانية: ٣ط.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعطيات غير كافية"],"answer":1,"explain":"نصف القطر ٢ سم، فمساحة الدائرة ٤ط ونصفها ٢ط، ولذلك ٣ط أكبر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"geometry","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-003","q":"كم عددًا يقبل القسمة على ٤ يمكن تكوينه من الأرقام (٧، ٣، ٤) دون تكرار؟","options":["٠","١","٢","٣"],"answer":0,"explain":"شرط القسمة على ٤ يعتمد على آخر رقمين، ولا واحد من ٧٣، ٧٤، ٣٧، ٣٤، ٤٧، ٤٣ يقبل القسمة على ٤.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"divisibility","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-004","q":"يبيّن رسم لإنتاج السيارات أن ألمانيا تنتج ٢٫٢٥ مليون سيارة سنويًا. كم سيارة تنتج شهريًا؟","options":["١٥٠٠٠٠","١٨٧٠٠٠","١٨٧٥٠٠","١٨٨٠٠٠"],"answer":2,"explain":"٢٫٢٥ مليون = ٢٢٥٠٠٠٠ سيارة، وبالقسمة على ١٢ شهرًا يكون المتوسط ١٨٧٥٠٠ سيارة.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"data-analysis","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-005","q":"محل عصائر لديه نوعان من العصير: مانجو وبرتقال. بكم طريقة يمكن اختيار ٤ أكواب عصير؟","options":["٢","٥","٨","١٠"],"answer":1,"explain":"يمكن اختيار ٠ أو ١ أو ٢ أو ٣ أو ٤ أكواب مانجو، والباقي برتقال؛ أي ٥ توزيعات.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"counting","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-006","q":"شخص معه ٤٥ ريالًا تتكوّن من ورقة من فئة ٥ ريالات وورقتين من فئة ١٠ ريالات وورقة من فئة ٢٠ ريالًا. يريد شراء كتاب دون أن يُرجع له البائع باقيًا. كم عدد القيم المختلفة الممكنة لسعر الكتاب؟","options":["٨","٩","١٠","١١"],"answer":1,"explain":"المبالغ الموجبة المختلفة التي يمكن تكوينها بهذه الأوراق هي ٥، ١٠، ١٥، ٢٠، ٢٥، ٣٠، ٣٥، ٤٠، ٤٥؛ أي ٩ قيم.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"counting","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-007","q":"إذا كان أ : ب = ٥ : ٨، وكان أ = ٢٠ص، فأوجد (أ + ب) بدلالة ص.","options":["٥٢ص","٣٢ص","٢٦ص","٤٨ص"],"answer":0,"explain":"٥ أجزاء = ٢٠ص، إذن الجزء = ٤ص، وب = ٨×٤ص = ٣٢ص؛ لذلك أ + ب = ٥٢ص.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"ratios","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-008","q":"٣ عمال يستغرقون ساعتين لدهان جدار طوله ١٢ قدمًا. كم ساعة يحتاج ٤ عمال لدهان جدار طوله ١٦ قدمًا بالمعدل نفسه؟","options":["١","١٫٥","٢","٢٫٥"],"answer":2,"explain":"الجدار الأول يحتاج ٦ ساعات-عامل لعدد ١٢ قدمًا؛ أي نصف ساعة-عامل لكل قدم. الجدار ١٦ قدمًا يحتاج ٨ ساعات-عامل، ومع ٤ عمال يحتاج ساعتين.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"work-rate","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-009","q":"مثلث قائم الزاوية ومتطابق الضلعين طول وتره ١٠ سم. ما مساحته؟","options":["١٠٠","٥٠","٢٥","١٢٫٥"],"answer":2,"explain":"إذا كان طول كل ضلع قائم = س فإن ٢س² = ١٠٠، أي س² = ٥٠، والمساحة = ١/٢ س² = ٢٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"geometry","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-010","q":"قطعت عجلتان المسافة نفسها. نصف قطر العجلة الأولى س وتدور ٣٢ دورة، ونصف قطر العجلة الثانية ص وتدور ٨ دورات. أي العلاقات الآتية صحيحة؟","options":["ص = س","ص = ٢س","ص = ٤س","٤ص = س"],"answer":2,"explain":"بتساوي المسافتين: ٣٢×٢طس = ٨×٢طص، ومنه ص = ٤س.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"ratios","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-011","q":"عرض مستطيل يساوي ٢س ومساحته ٤س². أوجد مساحة مربع طول ضلعه يساوي طول قطر المستطيل.","options":["٢س²","٣س²","٤س²","٨س²"],"answer":3,"explain":"طول المستطيل = ٤س² ÷ ٢س = ٢س، فيكون مربع القطر = (٢س)² + (٢س)² = ٨س²، وهو مساحة المربع المطلوب.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"geometry","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-012","q":"اشترى شخص بنصف ما معه، ثم اشترى بثلث المبلغ المتبقي. ما نسبة ما تبقى معه من المبلغ الأصلي؟","options":["١/٦","١/٥","١/٤","١/٣"],"answer":3,"explain":"بعد الشراء الأول بقي ١/٢، وبعد إنفاق ثلث المتبقي يبقى ٢/٣ منه؛ أي (١/٢)×(٢/٣)=١/٣.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"fractions","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-013","q":"كان سعر سهم يوم الأحد ١٠٠ ريال، ثم زاد يوم الثلاثاء ٢٠٪، ويوم الأربعاء زاد ١٠٪ عن سعر الثلاثاء. ما سعر السهم يوم الأربعاء؟","options":["١٢٠","١٣٢","١٣٤","١٤٤"],"answer":1,"explain":"١٠٠×١٫٢٠ = ١٢٠، ثم ١٢٠×١٫١٠ = ١٣٢ ريالًا.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"percentages","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-014","q":"كم عدد الأعداد الفردية المكوّنة من رقمين إذا كان رقم العشرات أكبر من ٣؟","options":["٢٠","٢٥","٣٠","٣٥"],"answer":2,"explain":"رقم العشرات له ٦ اختيارات من ٤ إلى ٩، ورقم الآحاد الفردي له ٥ اختيارات؛ فيكون العدد ٦×٥=٣٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"counting","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-015","q":"يمثل مخطط مصروفات سلطان الشهرية، وكان الطعام يمثل ٢٢٪ من إجمالي مصروفاته البالغ ٥٠٠٠ ريال. كم دفع للطعام؟","options":["٨٠٠","٩٠٠","١٠٠٠","١١٠٠"],"answer":3,"explain":"٢٢٪ من ٥٠٠٠ = ٠٫٢٢×٥٠٠٠ = ١١٠٠ ريال.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"percentages","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-016","q":"إذا كان ١/(٣ - ٢ن) > ١/٢٧، فقارن بين القيمة الأولى: ن، والقيمة الثانية: -١٠.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعطيات غير كافية"],"answer":3,"explain":"لكي يكون الطرف الأيسر موجبًا يلزم ن < ١٫٥، وبحل المتباينة ينتج ن > -١٢. إذن -١٢ < ن < ١٫٥، وقد يكون ن أكبر من -١٠ أو أصغر منه؛ فالمعطيات غير كافية.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"inequalities","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-017","q":"مربع طول ضلعه ١٠ سم، زاد طول ضلعه ٢ سم. ما نسبة الزيادة في مساحته؟","options":["٢٠٪","٢٥٪","٣٠٪","٤٤٪"],"answer":3,"explain":"المساحة تغيرت من ١٠٠ إلى ١٤٤ سم²، والزيادة ٤٤ من أصل ١٠٠؛ أي ٤٤٪.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"percentages","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-018","q":"لدى فصل ٤٠ طالبًا. يفضل ١/٨ منهم اللون الأحمر و١/٢ منهم اللون الأزرق، والباقي يفضل اللون الأصفر. كم طالبًا يفضل اللون الأصفر؟","options":["٥","١٠","١٥","٢٠"],"answer":2,"explain":"المتبقي = ١ - ١/٨ - ١/٢ = ٣/٨، وعددهم ٤٠×٣/٨ = ١٥ طالبًا.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"data-analysis","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-019","q":"وفق علاقة القياس ٢٠ بوصة = ٥٠ سم، كم سنتيمترًا تساوي ٨٠ بوصة؟","options":["٥٠","١٠٠","١٢٠","٢٠٠"],"answer":3,"explain":"٨٠ تساوي أربعة أمثال ٢٠، لذا القيمة بالسنتيمتر = ٤×٥٠ = ٢٠٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"proportions","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-020","q":"إذا كان √(س² + ١٢) = ٧، فما قيمة س الموجبة تقريبًا؟","options":["٤","٥","٦","٧"],"answer":2,"explain":"بالتربيع: س² + ١٢ = ٤٩، إذن س² = ٣٧، ومنه س ≈ ٦٫٠٨؛ أي تقريبًا ٦.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"radicals","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-021","q":"إذا كان م = ٣٩/٥٠، ون = ٥٩/١٠٠، ول = ٢٩٩/٥٠٠، فما ترتيب القيم تصاعديًا؟","options":["ن، ل، م","ن، م، ل","م، ن، ل","م، ل، ن"],"answer":0,"explain":"م = ٠٫٧٨، ن = ٠٫٥٩، ل = ٠٫٥٩٨؛ إذن ن < ل < م.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"fractions","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-022","q":"مستطيل قُسّم من نقطة ج على قاعدته بحيث ج د = ٣(ب ج). ورُسم المستقيم من ج إلى الرأس العلوي فوق ب، وكانت مساحة المثلث أ ب ج = ٧ سم². ما مساحة المستطيل؟","options":["١٤","٢١","٢٨","٥٦"],"answer":3,"explain":"إذا كان ب ج = س وارتفاع المستطيل = ع، فإن مساحة المثلث = ١/٢ س ع = ٧، أي س ع = ١٤. وعرض المستطيل = ٤س، فمساحته = ٤س ع = ٥٦.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"geometry","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-023","q":"إذا أعطى حمزة ٣ ريالات لإبراهيم أصبحت النسبة بين ما معهما ٢ : ١، وإذا أعطى إبراهيم حمزة ريالين أصبحت النسبة بينهما ٣ : ١. كم ريالًا كان مع حمزة؟","options":["١٧","٣٣","٤٣","٤٥"],"answer":2,"explain":"إذا كان مع حمزة ح ومع إبراهيم إ: ح-٣ = ٢(إ+٣) فينتج ح=٢إ+٩، وح+٢ = ٣(إ-٢) فينتج ح=٣إ-٨. بالمساواة إ=١٧ ثم ح=٤٣.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"ratios","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-024","q":"مستطيل طوله ٦ سم وعرضه ٣ سم. رُسم خط من نقطة على القاعدة تبعد ٤ سم عن الطرف الأيسر إلى الزاوية العلوية اليمنى، وظُلّل الجزء الواقع يسار الخط. ما مساحة الجزء المظلل؟","options":["١٢","١٥","١٨","٣٦"],"answer":1,"explain":"مساحة المستطيل ١٨ سم². المثلث غير المظلل قاعدته ٢ سم وارتفاعه ٣ سم، ومساحته ٣ سم²؛ إذن المظلل = ١٨-٣ = ١٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"geometry","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-025","q":"خزان مملوء إلى ثُمن سعته. إذا أضفنا إليه ٦٣ لترًا امتلأ بالكامل. كم لترًا سعة الخزان؟","options":["٧٠","٧٢","٧٥","٨٠"],"answer":1,"explain":"المقدار المضاف يمثل ٧/٨ من السعة. إذا كان ٧/٨ السعة = ٦٣، فإن السعة = ٦٣×٨÷٧ = ٧٢ لترًا.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"fractions","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"},{"id":"qdq-almonsef-s6-9-026","q":"احسب قيمة: ٢٥٠٢² - ٢٤٩٨².","options":["٥٠٠٠","١٠٠٠٠","٢٠٠٠٠","٤٠٠٠٠"],"answer":2,"explain":"باستخدام فرق مربعين: (٢٥٠٢-٢٤٩٨)(٢٥٠٢+٢٤٩٨)=٤×٥٠٠٠=٢٠٠٠٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"algebra","level":"practice","source":"تفريغ تعليمي من الفيديو المرفوع: شرح أقسام المنصف كمي - الأقسام من 6، 7، 8، 9"}];
